INSERT INTO prop_firms (name,description,logo_text,is_active) SELECT 'سرمایه گذار برتر', 'پلن‌های A و B، پلتفرم MT5 و ضوابط افت سرمایه و برداشت متفاوتی گزارش شده است.', 'SGB', true WHERE NOT EXISTS (SELECT 1 FROM prop_firms WHERE name IN ('سرمایه گذار برتر','سرمایه‌گذار برتر','SGB'));
INSERT INTO firm_details(firm_id,content) SELECT id, '{"introduction": "پلن‌های A و B، پلتفرم MT5 و ضوابط افت سرمایه و برداشت متفاوتی گزارش شده است.", "history": "در منبع سال معرفی ۲۰۲۱ ذکر شده است.", "tradingRules": "افت روزانه ۵٪ و افت کل ۱۲٪ در منبع آمده؛ شرایط طرح را بررسی کنید.", "payoutRules": "سهم سود بسته به نوع طرح و نوبت برداشت تفاوت دارد.", "facts": [{"label": "پلتفرم", "value": "MT5"}, {"label": "محدوده حساب", "value": "هزار تا ۲۰۰هزار دلار بسته به پلن"}], "pros": [], "cons": [], "plans": [], "faqs": [], "discounts": [], "customHtml": ""}'::jsonb FROM prop_firms WHERE name IN ('سرمایه گذار برتر','سرمایه‌گذار برتر','SGB') ON CONFLICT(firm_id) DO NOTHING;
INSERT INTO prop_firms (name,description,logo_text,is_active) SELECT 'کامبت کپیتال', 'پلن‌های اکسپرس و ماراتن و پلتفرم‌های MT4 و MT5 در گزارش معرفی شده‌اند.', 'TC', true WHERE NOT EXISTS (SELECT 1 FROM prop_firms WHERE name IN ('کامبت کپیتال','کامبت','Traders Combat'));
